// Pochette de la playlist (public/playlist-cover.jpg) encodée en base64 : un
// fichier lu sur disque n'est pas déployé avec l'Edge Function.
// À régénérer si l'image change.
export const COVER_IMAGE_BASE64 =
  "";

// Contrôle d'intégrité au démarrage (copie Edge Function uniquement) : une
// erreur de recopie du base64 se signale dans les logs de la fonction au lieu
// de faire échouer l'upload de la pochette en silence.
const COVER_IMAGE_SHA256 =
  "d9224a6b550aac597eaa3c2df0d074e0bfc0b15815ab55a44e5f9e286b163c37";
try {
  const digest = await crypto.subtle.digest(
    "SHA-256",
    Uint8Array.from(atob(COVER_IMAGE_BASE64), (c) => c.charCodeAt(0)),
  );
  const sha = [...new Uint8Array(digest)]
    .map((b) => b.toString(16).padStart(2, "0"))
    .join("");
  if (sha === COVER_IMAGE_SHA256) console.log("Pochette OK (sha256 vérifié)");
  else console.error(`Pochette corrompue : sha256 ${sha} au lieu de ${COVER_IMAGE_SHA256}`);
} catch (error) {
  console.error("Pochette illisible :", error);
}
